// #cea3ed (6a993d7ae4562a7e48cea3ed) «ניהול הזמנות ומשתמשים קיימים בעסק» — действия менеджера с ожидающим приглашением
// на /settings/users: меню «העתקת קישור / שליחה חוזרת / ביטול ההזמנה», новая ссылка гасит прежнюю (AC1), отмена гасит ссылку
// и показывает путь к менеджеру (AC2). Кейс BIZ-INV-012 · spec: specs/business-lifecycle.md (раздел 10) · seed: tests/seed.business.spec.ts.
// Данные: приглашение QA-AUTO-cea3ed-<stamp> на delivered+…@resend.dev (тестовый приёмник Resend, реальному человеку не уходит)
// создаётся и отменяется самим тестом (@data). Чужие строки и сохранённые аккаунты не трогаются. По ссылке не вступаем (пароль).
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#cea3ed #6a993d7ae4562a7e48cea3ed';

const isInviteUser = (url: string, method: string) => method === 'POST' && /\/functions\/v1\/invite-user/.test(url);
const isResend = (url: string) => url.includes('/functions/v1/resend-invitation');
const isCancel = (url: string) => url.includes('/rpc/cancel_invitation');

async function openRowMenu(page: Page, name: string) {
  const menuName = `פעולות עבור ההזמנה של ${name}`;
  await page.getByRole('button', { name: menuName }).click();
  const menu = page.getByRole('menu', { name: menuName });
  await expect(menu).toBeVisible();
  return menu;
}

async function expectJoinForm(guest: Page) {
  await expect(guest.getByRole('heading', { level: 1, name: 'הצטרפות לחשבון העסק' })).toBeVisible();
  await expect(guest.getByRole('textbox', { name: 'סיסמה', exact: true })).toBeVisible();
}

async function cancelInvitationCleanup(page: Page, name: string) {
  await page.goto('/settings/users');
  const row = page.getByTestId('user-row').filter({ hasText: name }).filter({ hasText: 'ממתין להצטרפות' });
  if ((await row.count()) === 0) return;
  const menu = await openRowMenu(page, name);
  await menu.getByRole('menuitem', { name: 'ביטול ההזמנה' }).click();
  await page.getByRole('dialog').or(page.getByRole('alertdialog')).getByRole('button', { name: 'ביטול ההזמנה', exact: true }).click();
  await expect(row).toHaveCount(0);
}

test.describe(`Пользователи и приглашения — действия с ожидающим приглашением (${HASH})`, () => {
  test(`business: меню приглашения «העתקת קישור / שליחה חוזרת / ביטול ההזמנה»; повтор — новая ссылка, прежняя «ההזמנה בוטלה»; отмена — ссылка «ההזמנה בוטלה» с путём к менеджеру @desktop @data ${HASH}`, async ({ page, context, asUser }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);
    const stamp = `${Date.now()}`;
    const name = `QA-AUTO-cea3ed-${stamp}`;
    const email = `delivered+qa-auto-cea3ed-${stamp}@resend.dev`;
    let cancelled = false;

    // 1. Создать своё приглашение (как BIZ-INV-010).
    await page.goto('/settings/users');
    await expect(page.getByRole('heading', { level: 1, name: 'משתמשים והרשאות' })).toBeVisible();
    await page.getByRole('button', { name: 'הזמנת משתמש' }).click();
    const inviteDialog = page.getByTestId('invite-user-dialog');
    await expect(inviteDialog).toBeVisible();
    await inviteDialog.getByLabel('שם מלא').fill(name);
    await inviteDialog.getByLabel('מייל', { exact: true }).fill(email);
    const createdP = page.waitForResponse((r) => isInviteUser(r.url(), r.request().method()));
    await inviteDialog.getByRole('button', { name: 'שליחת הזמנה' }).click();
    const created = await createdP;
    expect(created.status(), 'invite-user').toBe(200);
    const createdBody = (await created.json()) as { invitation?: { token?: string; delivery_status?: string } };
    expect(createdBody?.invitation?.delivery_status, 'delivery_status (resend.dev — доставлено)').toBe('sent');
    test.info().annotations.push({ type: 'test-data', description: `invitation ${name} <${email}> (отменяется в тесте)` });

    try {
      await expect(inviteDialog).toBeHidden();
      const row = page.getByTestId('user-row').filter({ hasText: name });
      await expect(row).toHaveCount(1);
      await expect(row).toContainText('ממתין להצטרפות');

      // 2. Меню ожидающего приглашения: только действия приглашения (треб.1).
      let menu = await openRowMenu(page, name);
      for (const item of ['העתקת קישור', 'שליחה חוזרת', 'ביטול ההזמנה']) {
        await expect(menu.getByRole('menuitem', { name: item })).toBeVisible();
      }
      for (const item of ['שינוי הרשאה', 'חסימת משתמש', 'הסרה מהעסק']) {
        await expect(menu.getByRole('menuitem', { name: item })).toHaveCount(0);
      }

      // 3. «העתקת קישור» — в буфере ссылка /invite/<token> этого приглашения; гость видит форму.
      await menu.getByRole('menuitem', { name: 'העתקת קישור' }).click();
      const origin = new URL(page.url()).origin;
      await expect.poll(() => page.evaluate(() => navigator.clipboard.readText()), { message: 'буфер — ссылка приглашения' }).toMatch(
        new RegExp(`^${origin.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/invite/[^/?#\\s]+$`),
      );
      const firstLink = await page.evaluate(() => navigator.clipboard.readText());
      const firstToken = firstLink.split('/invite/')[1];
      if (createdBody?.invitation?.token) expect(firstToken, 'скопирована ссылка именно этого приглашения').toBe(createdBody.invitation.token);
      const guest = await asUser('guest');
      await guest.goto(firstLink);
      await expectJoinForm(guest);

      // 4. «שליחה חוזרת» — новый token, статус остаётся ממתין להצטרפות (AC1).
      menu = await openRowMenu(page, name);
      const resentP = page.waitForResponse((r) => isResend(r.url()));
      await menu.getByRole('menuitem', { name: 'שליחה חוזרת' }).click();
      const confirmResend = page.getByRole('dialog').or(page.getByRole('alertdialog')).getByRole('button', { name: /^(שליחה חוזרת|שליחה מחדש|שליחה|אישור)$/ });
      const resent = await Promise.race([
        resentP,
        // Если перед отправкой спрашивают подтверждение — подтвердить; если нет — ожидание просто уступает ответу.
        confirmResend
          .waitFor({ state: 'visible', timeout: 5_000 })
          .then(async () => {
            await confirmResend.click();
            return resentP;
          })
          .catch(() => resentP),
      ]);
      expect(resent.status(), 'resend-invitation').toBe(200);
      const newToken = ((await resent.json()) as { invitation: { token: string } }).invitation.token;
      expect(newToken, 'новый token после «שליחה חוזרת»').toBeTruthy();
      expect(newToken).not.toBe(firstToken);
      await expect(row).toHaveCount(1);
      await expect(row).toContainText('ממתין להצטרפות');

      // 5. Прежняя ссылка отменена (AC1 «הקישור הקודם מתבטל», треб.3), новая — форма.
      await guest.goto(firstLink);
      await expect(guest.getByRole('heading', { level: 1, name: 'ההזמנה בוטלה' })).toBeVisible();
      await expect(guest.getByText('נשלחה הזמנה חדשה במקום ההזמנה הזו, ולכן הקישור הזה כבר לא פעיל.', { exact: false })).toBeVisible();
      await expect(guest.getByRole('textbox')).toHaveCount(0);
      const newLink = `${origin}/invite/${newToken}`;
      await guest.goto(newLink);
      await expectJoinForm(guest);

      // 6. Окно отмены и «השארת ההזמנה» — ничего не меняется.
      let cancelCalls = 0;
      page.on('request', (r) => {
        if (isCancel(r.url())) cancelCalls += 1;
      });
      menu = await openRowMenu(page, name);
      await menu.getByRole('menuitem', { name: 'ביטול ההזמנה' }).click();
      const cancelDialog = page.getByRole('dialog').or(page.getByRole('alertdialog'));
      await expect(cancelDialog).toContainText(`לבטל את ההזמנה של ${name}?`);
      await expect(cancelDialog).toContainText(
        'הקישור יפסיק לפעול מיד. מי שיפתח אותו יראה שההזמנה בוטלה ויתבקש לפנות למנהל/ת החשבון. אפשר לשלוח הזמנה חדשה בכל עת.',
      );
      await expect(cancelDialog.getByRole('button', { name: 'ביטול ההזמנה', exact: true })).toBeVisible();
      await cancelDialog.getByRole('button', { name: 'השארת ההזמנה', exact: true }).click();
      await expect(cancelDialog).toBeHidden();
      await expect(row).toContainText('ממתין להצטרפות');
      expect(cancelCalls, '«השארת ההזמנה» не отменяет приглашение').toBe(0);

      // 7. Отмена.
      menu = await openRowMenu(page, name);
      await menu.getByRole('menuitem', { name: 'ביטול ההזמנה' }).click();
      const cancelP = page.waitForResponse((r) => isCancel(r.url()));
      await cancelDialog.getByRole('button', { name: 'ביטול ההזמנה', exact: true }).click();
      expect((await cancelP).ok(), 'cancel_invitation').toBeTruthy();
      cancelled = true;
      await expect(page.getByText('ההזמנה בוטלה', { exact: true })).toBeVisible();
      await expect(row.filter({ hasText: 'ממתין להצטרפות' })).toHaveCount(0);

      // 8. Ссылка отменённого приглашения — «ההזמנה בוטלה» и путь к менеджеру (AC2).
      await guest.goto(newLink);
      await expect(guest.getByRole('heading', { level: 1, name: 'ההזמנה בוטלה' })).toBeVisible();
      await expect(guest.getByText('מנהל/ת החשבון ביטל/ה את ההזמנה, ולכן הקישור כבר לא פעיל.', { exact: false })).toBeVisible();
      await expect(guest.getByText('איך מקבלים הזמנה חדשה?')).toBeVisible();
      await expect(guest.getByText('יש לפנות למנהל/ת החשבון בעסק שהזמין אותך ולבקש הזמנה חדשה.', { exact: false })).toBeVisible();
      await expect(guest.getByRole('textbox')).toHaveCount(0);
    } finally {
      if (!cancelled) await cancelInvitationCleanup(page, name);
    }
  });
});
